<script>
  import Icon from '../../Icon/Icon.svelte'

  let {
    ref = $bindable(null),
    class: klass = '',
    icon = 'tabler:x',
    iconClass = '',
    target = null,
    message = null,
    type = 'close', // close or cancel
    children,
    onclick = null,
    ...rest
  } = $props()

  let dialog = $state(null)

  function closeModal(event) {
    dialog = this.closest(`dialog`)
    if (type === 'cancel') dialog.requestClose(message || 'cancel')
    if (type === 'close') dialog.close(message || 'close')
    if (onclick) onclick(event)
  }
</script>

<button
  {...rest}
  bind:this={ref}
  class="button-icon {klass}"
  data-modal-trigger={target}
  onclick={closeModal}
>
  {#if children}
    {@render children()}
  {:else}
    <Icon class={iconClass} {icon} />
  {/if}
</button>
